ent/books/zizhi-tongjian/vol-292/year-0956/part-02/sources/library/tongjian-292-956-shouzhou-chuzhou/source.txt", "note": "《资治通鉴》后周纪三，段落 zizhi-tongjian-a63549944a71-p003472；电子底本待考，分段待核", "id": "da84093f-fcf7-5b56-bc62-1274c00d045a"}, {"title": "新五代史·卷四十九", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/3cf04308010988e93f2be2b3123fa7653105db77/content/books/zizhi-tongjian/vol-292/year-0956/part-02/sources/library/xinwudaishi-49-huangfu-captured/source.txt", "note": "《新五代史》卷四十九，段落 xin-wudaishi-b08f244b9241-p001910；EPUB电子本，纸本及异文待核", "id": "834d0d7c-ede9-5435-9849-30b8f8eaec05"}, {"title": "旧五代史·卷一百十六", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/5a3b20b2409dbdd33b6e5de146408af9c01bd45c/content/books/zizhi-tongjian/vol-292/year-0956/part-01/sources/library/jiuwudaishi-116-january-956/source.txt", "note": "《旧五代史》卷一百十六，段落 jiu-wudaishi-205deb4a7860-p002746；EPUB电子本，纸本及异文待核", "id": "99d896fc-1490-5cb9-8e99-a9d1b356c4b8"}, {"title": "宋史·巻一", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/2a8781f0b81874ff142e6f29547499414becd367/content/books/zizhi-tongjian/vol-291/year-0954/part-03/sources/library/songshi-1-zhao-kuangyin-name/source.txt", "note": "《宋史》巻一，段落 songshi-9c6e46fee832-p000508；EPUB电子本，纸本及异文待核", "id": "a4ad0a0c-6366-5e6b-9665-60db62bf3ff4"}, {"title": "宋史·卷263·列传二十二·窦仪传·请赦兖州胁从", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/a94812079efe6f0dad4431d10d0651494739b7f1/content/books/zizhi-tongjian/vol-290/year-0952/part-03/sources/library/songshi-263-dou-yi-clemency/source.txt", "note": "《宋史》卷263·列传二十二·窦仪传·请赦兖州胁从，段落 songshi-9c6e46fee832-p058265；已核上下文及传主，纸本及异文待核。", "id": "6f55505e-45f0-5881-92d6-f2f0841a15ed"}]'::jsonb)
