INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "柴荣", "aliases": ["郭荣", "柴榮", "郭榮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本姓柴，950年《资治通鉴》以郭荣记名，任贵州刺史、天雄牙内都指挥使。父亲柴守礼是郭威妻子柴氏的兄长，郭威在尚无儿子时收养他。《新五代史》记他幼年跟随姑母在郭威家成长。《旧五代史》的任职纪年与通鉴不同，分别保留。", "biography": null, "status": "draft", "id": "697c1a4f-b373-5a78-8b47-330fe349a424"}, {"name": "李重进", "aliases": ["李重進"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "沧州人，福庆长公主之子，郭威的外甥，生于太原。郭威在藩镇时期的将佐，952年任恩州团练使，逐渐受重用。《宋史》还记当年内殿职务变化，具体任日未载。生卒年尚未录入。", "biography": null, "status": "draft", "id": "9769d0fb-1d80-593e-9aa3-e4c22416f835"}, {"name": "李谷", "aliases": ["李穀"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：李谷，汝阴进士、送别友人。", "biography": null, "status": "draft", "id": "33cb8b51-1e37-5d5f-ab22-b339b991020d"}, {"name": "赵匡胤", "aliases": ["趙匡胤"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周宿卫将领，后来成为宋太祖。954年高平之战右军溃逃后，与张永德分率两翼反击北汉军。《宋史》本纪印证其率同列冲锋的记载。生卒年留待相应史料补录。", "biography": null, "status": "draft", "id": "ce0fe2a6-d446-50c7-b968-4245fd9693ad"}, {"name": "何延锡", "aliases": ["何延錫"], "era": "五代十国", "birth_year": null, "death_year": 956, "description": "南唐都监。956年正月涡口水战中被赵匡胤所率后周军杀死。生年未载。", "biography": null, "status": "draft", "id": "c8ce13c0-450a-519b-b2c4-5a533d9c0519"}, {"name": "王逵", "aliases": ["王进逵", "王進逵"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国朗州静江军指挥使。《新五代史》称王进逵，记为武陵人，早年是静江军士卒。951年与周行逢率修府士兵逃回朗州，参与当地军府事务。生卒年尚未录入。", "biography": null, "status": "draft", "id": "48ca3ee4-cced-5056-8a47-4394d3ad6237"}, {"name": "潘叔嗣", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "朗州人、刘言麾下牙将。952年任指挥使。史书称其果敢，与周行逢、张文表交好、共同成事。生卒年未载。", "biography": null, "status": "draft", "id": "0aa70d0f-a11c-50f9-a0e8-3e0a7278f26d"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "何敬洙", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐天威都虞候。945年李璟任他为建州行营招讨马步都指挥使，与祖全恩、姚凤率数千兵增援查文徽，攻建州。生卒年本段未载。", "biography": null, "status": "draft", "id": "775d369d-2375-51d0-bcd1-b59c3a78d7c1"}, {"name": "司超", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "元城人，后周巡检使。956年二月奏报在盛唐击败南唐兵并俘高弼等。《通鉴》职名中庐、拜、光、黄的拜字可疑，《旧五代史》记庐寿巡检使，字形及职辖详略保留待核。", "biography": null, "status": "draft", "id": "8768f754-a204-5b14-ad70-40fb57a9f90d"}, {"name": "高弼", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐都监。956年二月在盛唐战败后被后周军俘获，《旧五代史》同时称其为吉州刺史。生卒年未载。", "biography": null, "status": "draft", "id": "7d2ed14c-08bc-54a5-a583-91f9ec0d8147"}, {"name": "皇甫晖", "aliases": ["皇甫暉"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷274同光四年条所见人物：皇甫晖。", "biography": null, "status": "draft", "id": "a1bbff11-3e05-52a8-a3c1-7e24adc029a5"}, {"name": "姚凤", "aliases": ["姚鳳"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐将领。945年李璟任他为建州行营都监，与何敬洙、祖全恩率军增援查文徽。生卒年本段未载。", "biography": null, "status": "draft", "id": "74f180a4-a1e3-5952-a5d4-9d936d1a19ac"}, {"name": "赵弘殷", "aliases": ["趙弘殷"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周马军副都指挥使，赵匡胤的父亲，后来由宋朝追尊为宣祖。956年滁州战事后夜间来到城下，赵匡胤以城门属公务为由拒绝夜开，翌晨才准入。生卒年留待对应史料补录。", "biography": null, "status": "draft", "id": "de2634c6-0020-50a7-a597-de7e816d9604"}, {"name": "窦仪", "aliases": ["竇儀"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "蓟州人，后晋天平军观察判官。944年正月奉颜衎命向朝廷奏报周儒降契丹、引兵渡河及蔡行遇被俘，并向景延广说明与杨光远会合的危险。生卒年本批未核。", "biography": null, "status": "draft", "id": "9d318328-3904-5714-a390-ea527c3e9fd9"}, {"name": "马崇祚（后周左金吾卫将军）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周左金吾卫将军。956年二月获命主管滁州事务。与946年契丹客省副使、暂掌恒州的同名主体缺少连贯履历证据，暂分档保存。生卒年未载。", "biography": null, "status": "draft", "id": "bdb33e67-54d2-50d3-87b1-65ffb8ecaf90"}, {"name": "刘词", "aliases": ["劉詞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋奉国都指挥使，元城人。942年与王清率军先登襄州。生卒年未载。", "biography": null, "status": "draft", "id": "1d26caf6-67d4-52b5-a6df-b9dff192cea5"}, {"name": "赵普", "aliases": ["趙普"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "蓟人，字则平。早年为刘词幕僚，获刘词遗表推荐；956年滁州攻取后，范质荐任军事判官。赵匡胤与其交谈后赏识他。面对百余名被捕者拟处死，赵普请求先审讯，再决定处罚，使多数人保全性命。", "biography": null, "status": "draft", "id": "639a1338-0a6d-5de9-8169-f35cbc62dcd9"}, {"name": "范质", "aliases": ["范質", "範質"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "宗城人，后晋主客员外郎。944年六月戊辰任翰林学士。后续仕宦随编年主线补录。生卒年本次引文未载。", "biography": null, "status": "draft", "id": "abe2c0af-4bf3-551b-83c9-f355ba085a0e"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "柴荣到永宁镇，主张先安抚寿州周边农民，使其安心务业", "start_year": 956, "end_year": 956, "time_original": "956年正月壬子", "dynasty": "五代十国", "description": "柴荣到永宁镇，主张先安抚寿州周边农民，使其安心务业。", "phases": [], "location_name": "永宁镇及寿州周边", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "3570ea69-3f18-5d5c-a3a7-918c1928a25f"}, {"title": "柴荣到正阳后，以李重进代李谷统率淮南行营", "start_year": 956, "end_year": 956, "time_original": "956年正月甲寅", "dynasty": "五代十国", "description": "柴荣到正阳后，以李重进代李谷统率淮南行营。", "phases": [], "location_name": "正阳", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "618c48dd-07b6-5ef2-90da-94c38c3e9d3a"}, {"title": "柴荣在淝水北侧设营，命诸军围寿州并迁浮桥到下蔡", "start_year": 956, "end_year": 956, "time_original": "956年正月丙辰", "dynasty": "五代十国", "description": "柴荣到寿州城下，在淝水之阳设营，命诸军围城，并安排将正阳浮桥移到下蔡镇。阳为水之北侧，具体营址尚未核实。", "phases": [], "location_name": "寿州城下、淝水之阳、正阳至下蔡", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "da7fd01f-f4b0-567e-a1a2-fd13dadb3f23"}, {"title": "柴荣征发多州数十万丁夫，参与寿州攻城，昼夜不息", "start_year": 956, "end_year": 956, "time_original": "956年正月丁巳", "dynasty": "五代十国", "description": "柴荣征发多州数十万丁夫，参与寿州攻城，昼夜不息。", "phases": [], "location_name": "寿州城下；民夫来自宋、毫、陈、颍、徐、宿、许、蔡等州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "adfc5315-5a5d-575a-8628-5d6d0b79121f"}, {"title": "南唐万余兵系船淮上，在涂山下设营", "start_year": 956, "end_year": 956, "time_original": "956年正月涡口战事前，具体设营日未载", "dynasty": "五代十国", "description": "南唐万余兵系船淮上，在涂山下设营。", "phases": [], "location_name": "淮水及涂山下", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "e952acea-a538-5aa5-8d7d-b678c7ba7da8"}, {"title": "赵匡胤以诱敌伏击在涡口击败南唐兵，杀何延锡并夺船", "start_year": 956, "end_year": 956, "time_original": "956年正月庚申条所记命令及交战；《旧五代史》壬戌奏报", "dynasty": "五代十国", "description": "柴荣命赵匡胤攻击南唐军。赵匡胤派百余骑逼近营地后假装逃走，以伏兵拦击，南唐兵在涡口败退，都监何延锡等被杀，战舰五十余艘被夺。太祖皇帝是后来的宋朝称号，赵匡胤当时仍为后周将领。", "phases": [], "location_name": "涡口", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "2a6588f1-5c6e-59fe-8fe0-e1a5655b53ab"}, {"title": "柴荣命王逵为南面行营都统，进攻南唐鄂州", "start_year": 956, "end_year": 956, "time_original": "956年正月条所记，具体诏日未载", "dynasty": "五代十国", "description": "柴荣命王逵为南面行营都统，进攻南唐鄂州。", "phases": [], "location_name": "湖南至鄂州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "e4415c29-4e52-59c4-8e3a-986707005340"}, {"title": "王逵率兵过岳州，潘叔嗣备宴犒劳", "start_year": 956, "end_year": 956, "time_original": "956年王逵进兵途中，具体日未载", "dynasty": "五代十国", "description": "王逵率兵过岳州，潘叔嗣备宴犒劳。", "phases": [], "location_name": "岳州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "be689c76-766a-5d4d-a642-85965fb211d9"}, {"title": "王逵左右索求不满，指控潘叔嗣谋反，王逵发怒", "start_year": 956, "end_year": 956, "time_original": "956年王逵途经岳州时", "dynasty": "五代十国", "description": "《通鉴》记王逵左右索取无厌，未获满足者向王逵指控潘叔嗣谋反。王逵怒形于色，潘叔嗣因此惧怕不安。谋反在这里是指控，不写成已经核实的犯罪，也不提前录入后段潘叔嗣的行动。", "phases": [], "location_name": "岳州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "12f63972-431d-5b9f-aec2-0c7ff9774d22"}, {"title": "何敬洙拒绝将民众迁入城内，整地备战，获李璟认可", "start_year": 956, "end_year": 956, "time_original": "956年正月湖南兵将至时，具体日未载", "dynasty": "五代十国", "description": "何敬洙拒绝将民众迁入城内，整地备战，获李璟认可。", "phases": [], "location_name": "南唐武昌", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "8c6865b1-f545-5886-ad93-c41d5760a111"}, {"title": "下蔡浮桥建成，柴荣亲自察看", "start_year": 956, "end_year": 956, "time_original": "956年二月丙寅", "dynasty": "五代十国", "description": "下蔡浮桥建成，柴荣亲自察看。", "phases": [], "location_name": "下蔡", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "e33d6a79-e557-5358-9ee9-848790b5fec4"}, {"title": "司超奏报在盛唐击败三千余南唐兵，俘高弼并获船", "start_year": 956, "end_year": 956, "time_original": "956年二月戊辰奏报，交战日未单列", "dynasty": "五代十国", "description": "元城人司超奏报在盛唐击败南唐兵三千余人，俘都监高弼等，获战舰四十余艘。《通鉴》巡检辖区文字中的拜字可疑，《旧五代史》称庐寿巡检使，保留差异。", "phases": [], "location_name": "盛唐", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "b873dfde-4b00-5d64-8033-b6696b0fe65d"}, {"title": "柴荣释放盛唐战中被俘的高弼", "start_year": 956, "end_year": 956, "time_original": "956年二月戊辰奏报条所附处置，具体释放日未另载", "dynasty": "五代十国", "description": "柴荣释放盛唐战中被俘的高弼。", "phases": [], "location_name": "后周行在", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "cb7e823d-7f6c-51c6-afd2-a057f3582b53"}, {"title": "柴荣命赵匡胤急袭清流关，赵军从山后进击皇甫晖所部", "start_year": 956, "end_year": 956, "time_original": "956年二月戊辰奏报以后所叙，《资治通鉴》未单列战日；《旧五代史》壬申奏报", "dynasty": "五代十国", "description": "柴荣命赵匡胤急袭清流关，赵军从山后进击皇甫晖所部。", "phases": [], "location_name": "清流关", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "cfecf9e8-5513-5dff-ab5d-b252bf3f72e1"}, {"title": "赵匡胤追入滁州，击伤并俘皇甫晖、姚凤，攻取城池", "start_year": 956, "end_year": 956, "time_original": "956年二月清流关失利之后，具体夺城日未单列", "dynasty": "五代十国", "description": "《通鉴》记皇甫晖等退入滁州，想断桥固守；赵匡胤率兵涉水追到城下，答应皇甫晖列阵请求，随后突入阵中击伤其头部，将皇甫晖、姚凤俘获并攻取滁州。伤者此时仍被生俘，未提前记为阵亡。", "phases": [], "location_name": "清流关至滁州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "05066e9b-7edb-5ff9-b562-1b4cd09da7c2"}, {"title": "赵弘殷夜抵滁州，赵匡胤以城门属公务拒绝夜开", "start_year": 956, "end_year": 956, "time_original": "956年二月滁州攻取后数日，具体日未载", "dynasty": "五代十国", "description": "赵弘殷夜抵滁州，赵匡胤以城门属公务拒绝夜开。", "phases": [], "location_name": "滁州城门", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "91de9427-a066-5d6b-84bc-a7357d2106f5"}, {"title": "柴荣派窦仪登记滁州府库财物", "start_year": 956, "end_year": 956, "time_original": "956年二月滁州攻取之后，具体日未载", "dynasty": "五代十国", "description": "柴荣派窦仪登记滁州府库财物。", "phases": [], "location_name": "滁州府库", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "a3a8f9ed-2a27-564f-a525-25043a20e0a1"}, {"title": "窦仪拒绝赵匡胤属吏无诏取绢，赵匡胤因此尊重他", "start_year": 956, "end_year": 956, "time_original": "956年二月滁州府库登记之后", "dynasty": "五代十国", "description": "窦仪拒绝赵匡胤属吏无诏取绢，赵匡胤因此尊重他。", "phases": [], "location_name": "滁州府库", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "774d8ad9-9c00-5259-9a44-1c7dce00843a"}, {"title": "柴荣任左金吾卫将军马崇祚主管滁州", "start_year": 956, "end_year": 956, "time_original": "956年二月滁州攻取之后，具体诏日未载", "dynasty": "五代十国", "description": "柴荣任左金吾卫将军马崇祚主管滁州。", "phases": [], "location_name": "滁州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "1dd4c7f8-da73-5b50-93b8-f8c62d104458"}, {"title": "刘词在遗表中推荐幕僚赵普", "start_year": null, "end_year": null, "time_original": "刘词去世前的遗表回述，具体作表年日未单列", "dynasty": "五代十国", "description": "刘词在遗表中推荐幕僚赵普。", "phases": [], "location_name": "永兴军至后周朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "35dae2ac-e980-50d3-9787-2a4c7d7d9b17"}, {"title": "滁州攻取后，范质荐赵普为军事判官", "start_year": 956, "end_year": 956, "time_original": "956年二月滁州平定之后", "dynasty": "五代十国", "description": "滁州攻取后，范质荐赵普为军事判官。", "phases": [], "location_name": "滁州及后周朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "82bc4267-cbd4-5d20-9ae6-6024ec1acc39"}, {"title": "赵匡胤与赵普交谈后对他产生好感", "start_year": 956, "end_year": 956, "time_original": "956年二月滁州判官荐任之后，具体日未载", "dynasty": "五代十国", "description": "赵匡胤与赵普交谈后对他产生好感。", "phases": [], "location_name": "滁州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "eff0375e-e614-5666-abdb-fbbdf6f026fe"}, {"title": "赵普请求先审讯拟处死的百余被捕者，使多数人活命", "start_year": 956, "end_year": 956, "time_original": "956年二月滁州平定之后，具体日未载", "dynasty": "五代十国", "description": "《通鉴》记百余名被捕为盗者原拟处死，赵普请求先审讯再决定刑罚，约七八成得以活命，赵匡胤更加赏识他。人数与比例都是史载约数，不换算成精确获救人数，也不把所有被捕者都写成已定罪。", "phases": [], "location_name": "滁州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "d514875b-6002-516b-b72f-0adc95c617f3"}, {"title": "赵匡胤回应战场装束显眼的提醒，表示有意让敌人识认", "start_year": null, "end_year": null, "time_original": "赵匡胤从军期间的习惯及对话回述，具体年份和日期未载", "dynasty": "五代十国", "description": "《通鉴》概述赵匡胤威名渐盛，临阵时常以繁缨装饰马匹、穿戴鲜明铠甲。有人提醒容易被敌军识认，他回答自己正希望敌人认得。这是习惯和对话的概述，不强定为956年二月某次具体交战。", "phases": [], "location_name": "战场，具体地点未载", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "ddfe4b26-8f2c-5859-b2ff-8367be1dc55f"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

