SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "柴荣到永宁镇，主张先安抚寿州周边农民，使其安心务业。", "citation": "卷292·显德三年（956年正月至二月及相关追述）·zztj-v292-y0956-p007·原文件第80行", "note": "原文：壬子，帝至永宁镇，谓侍臣曰：“闻寿州围解，农民多归村落，今闻大军至，必复入城。怜其聚为饿殍，宜先遣使存抚，各令安业。”；核对说明：农民将再入城、可能饥死是柴荣的担忧，《资治通鉴》本句未证明所有人已聚城饿死，也未逐项记使者完成任务。", "status": "draft", "id": "ca538e70-64cb-510c-89eb-f0af1de1ed66", "subject_id": "3570ea69-3f18-5d5c-a3a7-918c1928a25f", "source_id": "da84093f-fcf7-5b56-bc62-1274c00d045a"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "956年正月壬子", "citation": "卷292·显德三年（956年正月至二月及相关追述）·zztj-v292-y0956-p007·原文件第80行", "note": "原文：壬子，帝至永宁镇，谓侍臣曰：“闻寿州围解，农民多归村落，今闻大军至，必复入城。怜其聚为饿殍，宜先遣使存抚，各令安业。”；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "24e17567-c56d-5796-909f-df22d638eb06", "subject_id": "3570ea69-3f18-5d5c-a3a7-918c1928a25f", "source_id": "da84093f-fcf7-5b56-bc62-1274c00d045a"}, {"subject_table": "person", "field_path": "description", "claim_text": "柴荣：担心军队再临使农民聚城受饥，提出先派人安抚。", "citation": "卷292·显德三年（956年正月至二月及相关追述）·zztj-v292-y0956-p007·原文件第80行", "note": "原文：壬子，帝至永宁镇，谓侍臣曰：“闻寿州围解，农民多归村落，今闻大军至，必复入城。怜其聚为饿殍，宜先遣使存抚，各令安业。”；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "c099ea02-6602-5be4-8b55-b465b4f95408", "subject_id": "697c1a4f-b373-5a78-8b47-330fe349a424", "source_id": "da84093f-fcf7-5b56-bc62-1274c00d045a"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "柴荣：担心军队再临使农民聚城受饥，提出先派人安抚。", "citation": "卷292·显德三年（956年正月至二月及相关追述）·zztj-v292-y0956-p007·原文件第80行", "note": "原文：壬子，帝至永宁镇，谓侍臣曰：“闻寿州围解，农民多归村落，今闻大军至，必复入城。怜其聚为饿殍，宜先遣使存抚，各令安业。”；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "b4592248-5c5d-52c4-a636-dedcbcbc8e8c", "subject_id": "eda202a7-db94-57a2-abcf-492b6106fb32", "source_id": "da84093f-fcf7-5b56-bc62-1274c00d045a"}, {"subject_table": "event", "field_path": "description", "claim_text": "柴荣到正阳后，以李重进代李谷统率淮南行营。", "citation": "卷292·显德三年（956年正月至二月及相关追述）·zztj-v292-y0956-p007·原文件第80行", "note": "原文：甲寅，帝至正阳，以李重进代李谷为淮南道行营都招讨使，以谷判寿州行府事。；核对说明：按原文动作分录；不外推原因与结果。", "status": "draft", "id": "66f5fdf1-3cbb-59eb-abab-3c0f35f2e7ce", "subject_id": "618c48dd-07b6-5ef2-90da-94c38c3e9d3a", "source_id": "da84093f-fcf7-5b56-bc62-1274c00d045a"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "956年正月甲寅", "citation": "卷292·显德三年（956年正月至二月及相关追述）·zztj-v292-y0956-p007·原文件第80行", "note": "原文：甲寅，帝至正阳，以李重进代李谷为淮南道行营都招讨使，以谷判寿州行府事。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "6669be3e-b5a5-59b9-a1a3-4a7102e54583", "subject_id": "618c48dd-07b6-5ef2-90da-94c38c3e9d3a", "source_id": "da84093f-fcf7-5b56-bc62-1274c00d045a"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "柴荣：更换行营统帅。", "citation": "卷292·显德三年（956年正月至二月及相关追述）·zztj-v292-y0956-p007·原文件第80行", "note": "原文：甲寅，帝至正阳，以李重进代李谷为淮南道行营都招讨使，以谷判寿州行府事。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "690ec189-d3cf-515a-adae-8cd169c8dacd", "subject_id": "d701d183-0229-5df9-ac17-8bbcefa71c17", "source_id": "da84093f-fcf7-5b56-bc62-1274c00d045a"}, {"subject_table": "person", "field_path": "description", "claim_text": "李重进：任淮南道行营都招讨使。", "citation": "卷292·显德三年（956年正月至二月及相关追述）·zztj-v292-y0956-p007·原文件第80行", "note": "原文：甲寅，帝至正阳，以李重进代李谷为淮南道行营都招讨使，以谷判寿州行府事。；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "986d8487-224c-557e-a663-a69556e97e37", "subject_id": "9769d0fb-1d80-593e-9aa3-e4c22416f835", "source_id": "da84093f-fcf7-5b56-bc62-1274c00d045a"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "李重进：任淮南道行营都招讨使。", "citation": "卷292·显德三年（956年正月至二月及相关追述）·zztj-v292-y0956-p007·原文件第80行", "note": "原文：甲寅，帝至正阳，以李重进代李谷为淮南道行营都招讨使，以谷判寿州行府事。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "194edea0-c236-5621-856e-7d8043e8dd6a", "subject_id": "7a82c5ec-2879-5287-b9b9-d6b0bbc2bb94", "source_id": "da84093f-fcf7-5b56-bc62-1274c00d045a"}, {"subject_table": "person", "field_path": "description", "claim_text": "李谷：转判寿州行府事务。", "citation": "卷292·显德三年（956年正月至二月及相关追述）·zztj-v292-y0956-p007·原文件第80行", "note": "原文：甲寅，帝至正阳，以李重进代李谷为淮南道行营都招讨使，以谷判寿州行府事。；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "f1e7cf9a-591a-5352-8e12-b6bf683be672", "subject_id": "33cb8b51-1e37-5d5f-ab22-b339b991020d", "source_id": "da84093f-fcf7-5b56-bc62-1274c00d045a"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "李谷：转判寿州行府事务。", "citation": "卷292·显德三年（956年正月至二月及相关追述）·zztj-v292-y0956-p007·原文件第80行", "note": "原文：甲寅，帝至正阳，以李重进代李谷为淮南道行营都招讨使，以谷判寿州行府事。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "d1bd640b-5c33-50cd-9b13-7d90840494b1", "subject_id": "112a9133-62ca-5789-9447-c3c5963e809b", "source_id": "da84093f-fcf7-5b56-bc62-1274c00d045a"}, {"subject_table": "event", "field_path": "description", "claim_text": "《旧五代史》同日记柴荣到正阳，以及李重进、李谷职务调整。", "citation": "《旧五代史》卷一百十六，段落 jiu-wudaishi-205deb4a7860-p002746；EPUB电子本，纸本及异文待核", "note": "原文：甲寅，車駕至正陽。以侍衛都指揮使李重進為淮南道行營都招討使，命宰臣李穀判壽州行府事。；核对说明：李谷不是在此被全部免官，沿《资治通鉴》判寿州行府职务。", "status": "draft", "id": "2afe490e-a0dc-5eb2-b4b4-7d7e222e02af", "subject_id": "618c48dd-07b6-5ef2-90da-94c38c3e9d3a", "source_id": "99d896fc-1490-5cb9-8e99-a9d1b356c4b8"}, {"subject_table": "event", "field_path": "description", "claim_text": "柴荣到寿州城下，在淝水之阳设营，命诸军围城，并安排将正阳浮桥移到下蔡镇。阳为水之北侧，具体营址尚未核实。", "citation": "卷292·显德三年（956年正月至二月及相关追述）·zztj-v292-y0956-p007·原文件第80行", "note": "原文：丙辰，帝至寿州城下，营于淝水之阳，命诸军围寿州，徙正阳浮梁于下蔡镇。；核对说明：阳沿史载方位为水之北岸，具体营址坐标未核；标题不另造现代营地。", "status": "draft", "id": "9d12e806-f2e0-5aac-b7b6-a7cd7eb21c09", "subject_id": "da7fd01f-f4b0-567e-a1a2-fd13dadb3f23", "source_id": "da84093f-fcf7-5b56-bc62-1274c00d045a"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "956年正月丙辰", "citation": "卷292·显德三年（956年正月至二月及相关追述）·zztj-v292-y0956-p007·原文件第80行", "note": "原文：丙辰，帝至寿州城下，营于淝水之阳，命诸军围寿州，徙正阳浮梁于下蔡镇。；核对说明：按《资治通鉴》及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。